﻿ 	 Arrow functions are a shorter and simpler way to write functions. They were introduced in ES6 (ES2015).

Example Traditional Function:

function add(a, b) {
  return a + b;
} Arrow Function:

const add = (a, b) => a + b;

﻿ Document Properties alinkcolor: document.alinkcolor;
bgcolor: document.bgcolor;
Forms[]: document.forms[0];
Title: document.title;
URL: document.URL;

﻿ Class Declaration class Student{
   constructor(name,age){
     this.name = name; 
     this.age = age;
}
display()
{
console.log("name="+this.name); console.log("age="+this.age);
}
}
var obj = new Student('asd', 23); obj.display();

﻿ Class Expression var Student = class{
constructor(name, age){ this.name = name; this.age = age;
}
display()
{
console.log("name="+this.name); console.log("age="+this.age);
}
}
var obj = new Student('asd', 23); obj.display(); Useful when assigning/passing a class dynamically.

﻿ Example class parent{
constructor(name){ this.name = name;
}  }
class child extends parent{ display()
{
console.log("name="+this.name);
} }

var obj = new child('asd'); obj.display();

﻿ Example-Multilevel Inheritance class games{
display1()
{
console.log("Indoor and outdoor");
}
} class indoor extends games{ display2()
{
console.log("Chess");
}
}

class outdoor extends indoor{ display3()
{
console.log("Cricket");
}
} var obj = new outdoor(); obj.display1(); obj.display2(); obj.display3();

